 const uses=i=>A(PR().recipes).filter(r=>r.ingredientId===i.id).length,keep0=[...items].sort((a,b)=>uses(b)-uses(a)||(a.status==='غیرفعال')-(b.status==='غیرفعال'))[0];
 const q=x=>x===null||x===undefined||!Number.isFinite(Number(x))?'—':fa(+Number(x).toFixed(3));let keep=keep0.id;const facs={};
