/* prepared (composite) items: list and form (MenuWrite.savePreparedItem); delete = MenuWrite.deletePreparedItem (deleted only
   with no reference, archived when it has history, refused while an active menu item uses it); archived items are hidden unless shown */
let ppArch=false;
