if(pt){const a0=pt.actions;pt.actions=r=>IC.ready()?`<button class="btn btn-secondary" onclick="CatalogReal.supplierExport()">${P.ic('download')}خروجی Excel</button>${can('purchase')?`<button class="btn btn-secondary" onclick="CatalogReal.supplierImport()">${P.ic('file-spreadsheet')}ورود از Excel</button>`:''}`+btnFor('purchase','plus','تأمین‌کنندهٔ جدید','CatalogReal.supplierForm()'):(a0?a0(r):'')}
window.CatalogReal={priceOne,mergeForm,unitsForm,densityForm,structureForm,groupsForm,itemsImport,deleteItem,cleanupForm,preparedList,preparedForm,supplierListsForm,supplierExport,supplierImport,ingredientForm,pricesForm,menuForm,supplierForm,supplierItems:supplierItemsForm,supplierArchive,supplierFoot,assetForm,assetAction:()=>can('assets')?`<button class="btn btn-primary" onclick="CatalogReal.assetForm()">${P.ic('plus')}دارایی جدید</button>`:'',can,whyK};
